create or replace TABLE ETL.T_TCACHE_POS_RECEIPTLINE_LOAD_2_TCACHE_PRODUCT_RETAIL_LINE_INTERMEDIATE_POS08_2 cluster by (BUS_DT)(
	RETAIL_EVENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related retail transaction, i.e. for the sales_2 or return of products..',
	RETAIL_EVENT_LINE_SEQ NUMBER(38,0) NOT NULL COMMENT 'The number of the line in the retail event.',
	EVENT_START_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when the scanning (or the manual input) of the article started.',
	EVENT_END_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when the scanning (or the manual input) of the article was finished.',
	BUS_DT DATE NOT NULL COMMENT 'The business date on which the retail event is counted.',
	RETAIL_EVENT_END_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when the related retail event was finished.',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the store where the related retail event happend.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related country_2 organization.',
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL,
	CASH_REGISTER_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the cash register which has created this transaction.',
	CASH_REGISTER_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the type of cash register. (standard cash register, self-checkout system, vending machine)',
	CASH_REGISTER_USG_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the way, how a cash register is used. It distinguishes between regular operations, training and maintenance.',
	CASHIER_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the cashier. (The number is unique for a given store and a day.)',
	AUTH_BY_NR VARCHAR(20) COMMENT 'In case of a cancellation or any other non-standard operaion, the transaction must be authorized by the store manager or by another employee. This is the number which identifies the employee_2, who has authorized the transaction. (This is not an employee_2 number!)',
	CUST_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the customer.',
	PROD_RETAIL_LINE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for product retail lines.',
	RETAIL_EVENT_LINE_SCENARIO_ID NUMBER(38,0) NOT NULL COMMENT 'The numeric identifier for the scenario which is represented by the retail event line.',
	PROD_VARIANT_SIDX NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a sales_2 variant of a product.',
	PROD_VARIANT_INPUT_NR VARCHAR(100) COMMENT 'The number which identifies the product variant - as it has been scanned or manually keyed this. This can be an EAN_2, GTIN or a price lookup number (PLU)',
	PROD_VARIANT_INPUT_NR_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the kind of the number which has been scanned or typed in, in order to identify the product variant. The product variant number can be identified by an EAN_2, a GTIN or a product lookup number (PLU).',
	DISPLAYED_PROD_VARIANT_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the product variant, as it is printed on the receipt.',
	WEIGHT_BASED_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product variant was sold (or returned) by weight instead of count.',
	PROD_VARIANT_CNT NUMBER(38,0) COMMENT 'The number of this product variant which has been sold or returned. (This attribute is empty for weight-based products.)',
	PROD_VARIANT_QTY NUMBER(18,5) COMMENT 'In case of weight-based products, this is the quantity of the product which was sold or returned.',
	UOM_CD VARCHAR(20) COMMENT 'The code identifying the unit_2 of measure.',
	UNIT_PRICE NUMBER(38,5) NOT NULL COMMENT 'The price of a single unit_2 of the product variant, in the currency indicated by the currency code.',
	BASE_GROSS_VAL NUMBER(38,5) NOT NULL COMMENT 'The base gross amount of the sales_2 or return, i.e. quantity / count * unit_2 price. Discounts or price modifications are not considered.',
	RETAIL_LINE_GROSS_VAL NUMBER(38,5) NOT NULL COMMENT 'The gross amount of the sales_2 or return, i.e. quantity / count * unit_2 price. Discounts and price changes are considered.',
	RETAIL_LINE_NET_VAL NUMBER(38,5) NOT NULL COMMENT 'The net amount of the sales_2 or return, i.e. quantity / count * unit_2 price. Discounts and price changes are considered. (This is a calculated amount!)',
	RETAIL_LINE_VAT_VAL NUMBER(38,5) NOT NULL COMMENT 'The total amount of value added tax which was charged for this line.',
	TAX_CLASS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the tax class, e.g. Reduced VAT Rate.',
	GEO_AREA_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the geographical area to which the tax class applies.',
	TAX_PCT NUMBER(38,5) NOT NULL COMMENT 'The actual tax percentage which is valid for the given tax class. E.g. 19%',
	TURNOVER_RELEVANT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event line is to be considered as relevant for the turnover calculation. The flag is set to false, if the related retail event is not relevant for turnover or if the line has been cancelled.',
	PROD_ENTRY_METHOD_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the way, how the product was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
	PRICE_ENTRY_METHOD_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the way, how the unit_2 price was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
	PROD_RETURN_REASON_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the reasons why a product was returend to the store.',
	RETURN_TXT VARCHAR(1000) COMMENT 'A free text field describing the circumstances of the return.',
	ORIG_SALES_EVENT_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the sales_2 transaction in which the returned product was sold.',
	PARENT_LINE_SEQ NUMBER(38,0) COMMENT 'In case the line represents a deposit, this is the related base line.',
	CANCEL_LINE_SEQ NUMBER(38,0) COMMENT 'In case the product retail line is cancelled, this is the number of the related cancellation line.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_PRODUCT_RETAIL_LINE primary key (RETAIL_EVENT_SID, RETAIL_EVENT_LINE_SEQ)
);

